steps:
1. 고정 벡터 V(타임스탬프는 모두 요청에 명시, 서버 시계 비사용)를 확정한다:
   v1: snapshot=BASE+{"timestamp_s":1.0,"source_timestamp_s":1.0,"vehicle_speed_kph":5.0}, command=null
   v2: snapshot=BASE+{"timestamp_s":1.05,"source_timestamp_s":1.05}, command={"side":"all","action":"unlock","source":"avn"}
   v3: snapshot=BASE+{"timestamp_s":1.1,"source_timestamp_s":1.1,"rear_left_approach_risk":true}, command={"side":"left","action":"unlock","source":"voice"}
   v4: snapshot=BASE+{"timestamp_s":1.15,"source_timestamp_s":1.15,"rear_left_approach_risk":true}, command={"side":"left","action":"unlock","source":"voice"}
   v5: snapshot=BASE+{"timestamp_s":1.2,"source_timestamp_s":1.2,"isofix_right":true}, command=null
   v6: snapshot=BASE+{"timestamp_s":1.25,"source_timestamp_s":1.25,"crash_status":"PENDING"}, command=null
   v7: snapshot=BASE+{"timestamp_s":1.3,"source_timestamp_s":1.3,"crash_status":"CONFIRMED"}, command=null
   v8: snapshot=BASE+{"timestamp_s":1.35,"source_timestamp_s":1.35,"sensor_fault":true}, command={"side":"all","action":"lock","source":"mobile_app"}
   v9: snapshot=BASE+{"timestamp_s":1.4,"source_timestamp_s":1.4,"ignition_on":false}, command=null
   v10: snapshot=BASE+{"timestamp_s":1.45,"source_timestamp_s":1.45,"adult_present":true}, command=null
   v11: snapshot=BASE+{"timestamp_s":1.5,"source_timestamp_s":1.5,"fire_detected":true}, command=null
   v12: snapshot=BASE+{"timestamp_s":1.8,"source_timestamp_s":1.5}, command=null (경과 300 ms)
   v13: POST /tick {"timestamp_s":2.0}
   v14: snapshot=BASE+{"timestamp_s":2.05,"source_timestamp_s":2.05,"vehicle_speed_kph":-0.1}, command=null (422 거절)
   v15: snapshot=BASE+{"timestamp_s":2.1,"source_timestamp_s":2.1,"vehicle_speed_kph":3.0}, command={"side":"all","action":"unlock","source":"physical_button"}
